  function investOfflineHospitalCare(action,x,y){
    const b=state.buildings.find(o=>o.kind==='civic'&&o.x===x&&o.y===y&&['operativo','habilitado'].includes(o.status));
    if(!b||!offlineServiceModel(b)?.care)throw Error('La ampliación requiere un centro sanitario construido y habilitado.');
    if(!offlineRoadRoute({x:4,y:10},b))throw Error('El centro necesita acceso vial para recibir equipos y ambulancias.');
    const ward=b.hospitalWard;
    if(action==='openHospitalWard'&&ward)throw Error('Este centro ya dispone de internación.');
    if(action!=='openHospitalWard'&&!ward)throw Error('Primero hay que equipar una sala de internación.');
    if(action==='expandHospitalWard'&&(ward.beds||0)>=36)throw Error('La sala alcanzó su capacidad máxima de 36 camas.');
    if(action==='addAmbulance'&&(ward.ambulances||0)>=3)throw Error('Este centro admite hasta tres ambulancias.');
    const cost=HOSPITAL_COSTS[action];
    if(!cost)throw Error('Intervención sanitaria no reconocida.');
    const reserved=(state.projects||[]).filter(p=>!p.privatePaid).reduce((n,p)=>n+Math.max(0,(p.cost||0)-(p.paid||0)),0);
    if((state.money||0)-reserved<cost)throw Error('Fondos libres insuficientes después de reservar las obras municipales.');
    state.money-=cost;
    if(action==='openHospitalWard')b.hospitalWard={beds:12,ambulances:0,equippedDay:state.day};
    else if(action==='expandHospitalWard')ward.beds=Math.min(36,ward.beds+8);
    else ward.ambulances=(ward.ambulances||0)+1;
    event('Inversión hospitalaria',(b.name||'Centro de salud')+': '+action+'; inversión municipal $ '+cost+'. La atención depende del personal, las redes y las calles.');
    return b.hospitalWard;
  }
